// A camera turning slowly inside the cube map on channel 0.
mat2 turn(float a)
{
    float c = cos(a), s = sin(a);
    return mat2(c, -s, s, c);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 p = (2.0 * fragCoord - iResolution.xy) / iResolution.y;
    vec3 rd = normalize(vec3(p, 1.5));
    rd.yz = turn(0.25) * rd.yz;
    rd.xz = turn(0.6 * iTime) * rd.xz;
    vec3 sky = textureCube(iChannel0, rd).rgb;
    float horizon = 1.0 - abs(rd.y);
    float facing = 0.5 + 0.5 * rd.x;
    fragColor = vec4(0.1 + 0.1 * horizon + 0.3 * facing + 0.5 * sky, 1.0);
}
